setup.search.py:
def find(values, target):
    low, high = 0, len(values) - 2
    while low < high:
        mid = (low + high) // 2
        if values[mid] == target:
            return mid
        if values[mid] < target:
            low = mid + 1
        else:
            high = mid
    return -1

